import random
import string
from test.support import import_helper
grp = import_helper.import_module('grp')

def _t():
    try:
        grp.getgrgid()
    except TypeError:
        pass
    try:
        grp.getgrgid(*(3.14,))
    except TypeError:
        pass
    try:
        grp.getgrgid(*(0.0,))
    except TypeError:
        pass
    try:
        grp.getgrgid(*(0, 0))
    except TypeError:
        pass
    try:
        grp.getgrgid(*(2 ** 128,))
    except OverflowError:
        pass
    try:
        grp.getgrgid(*(-2 ** 128,))
    except OverflowError:
        pass
    try:
        grp.getgrnam()
    except TypeError:
        pass
    try:
        grp.getgrnam(*(42,))
    except TypeError:
        pass
    try:
        grp.getgrnam(*(b'root',))
    except TypeError:
        pass
    try:
        grp.getgrnam(*('root', 0))
    except TypeError:
        pass
    try:
        grp.getgrnam(*('a\x00b',))
    except ValueError:
        pass
    try:
        grp.getgrnam(*('root\x00',))
    except ValueError:
        pass
    try:
        grp.getgrnam(*('roo\udc74',))
    except UnicodeEncodeError:
        pass
    try:
        grp.getgrnam(*('',))
    except KeyError:
        pass
    try:
        grp.getgrall(*(42,))
    except TypeError:
        pass
    for _ in range(30):
        fakename = ''.join(random.choices(string.ascii_lowercase, k=6))
        try:
            grp.getgrnam(fakename)
        except KeyError:
            break
    else:
        raise AssertionError('Cannot find non-existent group name')
    maxgid = 2 ** 31
    for _ in range(30):
        fakegid = random.randrange(maxgid)
        try:
            grp.getgrgid(fakegid)
        except KeyError:
            break
        except OverflowError:
            if maxgid == 2 ** 31:
                maxgid = 2 ** 16 - 1
            elif maxgid == 2 ** 16 - 1:
                maxgid = 2 ** 15
            else:
                raise
    else:
        raise AssertionError('Cannot find non-existent gid')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
